// The example kitchen: an à-la-carte restaurant kitchen for about 120 covers, planned the way a
// kitchen planner would present it. It is built only through the public model API (catalog
// entries, `itemFromCatalog`, `variantPatch`), with fixed ids and a fixed date, so the files in
// `examples/` can be regenerated byte for byte (`examples/README.md`).
//
// Plan (x east, y south, mm): an L-shaped room of 13.2 × 9.6 m whose south-east corner is the
// dining room. Goods come in from the yard in the north wall, go to the stores in the north-west
// (dry store, cold room, freezer room), to preparation along the dish partition and the pastry
// island, to the cooking island with the heavy line on the north wall, and leave through the pass
// in the wall to the dining room. Dirty dishes come back from the dining room straight into the
// dish wash in the south-west wing.

import { catalogEntry, type Energy } from "../kinds/registry";
import { lRoom } from "../model/geometry";
import { FORMAT_VERSION, itemFromCatalog, variantPatch } from "../model/project";
import type { Item, Opening, Partition, Project } from "../model/types";
import { t, type Lang } from "../lib/i18n";

/** Inner size of the room and the dining room's corner cut out of it (mm). */
export const EXAMPLE_WIDTH = 13200;
export const EXAMPLE_DEPTH = 9600;
const DINING_CUT_WIDTH = 6900;
const DINING_CUT_DEPTH = 3200;

const ROOM_HEIGHT = 3200;
const WALL = 300;
const PARTITION = 150;
const DOOR_HEIGHT = 2135;

/** The date of the drawing: the example does not change with the day it is generated. */
const DATE = "2026-10-13";

/** Rotation by the side the unit's front faces: south (back on a north wall), north, west, east. */
const FACES = { south: 0, north: 180, west: 90, east: 270 } as const;
type Face = keyof typeof FACES;

type Zone = "goods" | "store" | "prep" | "pastry" | "cooking" | "island" | "pass" | "dish" | "building";

/** The zone of every item, written into its note: the equipment list reads like a room book. */
const ZONES: Record<Zone, Record<Lang, string>> = {
  goods: { de: "Wareneingang", en: "Goods receiving" },
  store: { de: "Lager", en: "Storage" },
  prep: { de: "Vorbereitung Gemüse, Fleisch und Fisch", en: "Preparation of vegetables, meat and fish" },
  pastry: { de: "Patisserie", en: "Pastry" },
  cooking: { de: "Kochwand", en: "Cooking wall" },
  island: { de: "Kochinsel", en: "Cooking island" },
  pass: { de: "Ausgabe", en: "Pass" },
  dish: { de: "Spülküche", en: "Dish wash" },
  building: { de: "Gebäude", en: "Building" },
};

interface Spec {
  catalogId: string;
  face: Face;
  /** North-west corner of the footprint (mm): the unit is placed by its outline, not its centre. */
  x: number;
  y: number;
  zone: Zone;
  width?: number;
  energy?: Energy;
  /** A depth other than the catalog's (only the island hoods, for their overhang). */
  depth?: number;
}

