const INFO: Record<Lang, { name: string; client: string }> = {
  de: { name: "Beispielküche Restaurant Lindenhof", client: "Restaurant Lindenhof (Beispiel)" },
  en: { name: "Example kitchen Restaurant Lindenhof", client: "Restaurant Lindenhof (example)" },
};

/** The item of one spec: the catalog's default, switched to its variant, placed by its corner. */
function specItem(spec: Spec, index: number, lang: Lang): Item {
  const entry = catalogEntry(spec.catalogId);
  if (!entry) throw new Error(`example kitchen: unknown catalog id ${spec.catalogId}`);
  let item = itemFromCatalog(entry, 0, 0, FACES[spec.face]);
  if (spec.width !== undefined || spec.energy !== undefined) {
    const change = { ...(spec.width !== undefined ? { width: spec.width } : {}), ...(spec.energy !== undefined ? { energy: spec.energy } : {}) };
    item = { ...item, ...variantPatch(item, entry, change) };
  }
  if (spec.depth !== undefined) item = { ...item, depth: spec.depth };
  // Turned a quarter, the footprint's extent along x is the depth.
  const across = spec.face === "west" || spec.face === "east";
  const ex = across ? item.depth : item.width;
  const ey = across ? item.width : item.depth;
  return {
    ...item,
    id: `ex-${String(index + 1).padStart(2, "0")}`,
    name: t(entry.name, undefined, lang),
    x: spec.x + ex / 2,
    y: spec.y + ey / 2,
    note: ZONES[spec.zone][lang],
  };
}

/** The example kitchen with names and notes in `lang`. Pure: the same project on every call. */
export function exampleKitchen(lang: Lang): Project {
  return {
    format: "kitchenplaner",
    version: FORMAT_VERSION,
    info: { ...INFO[lang], author: "Kitchenplaner", date: DATE },
    room: {
      points: lRoom(EXAMPLE_WIDTH, EXAMPLE_DEPTH, DINING_CUT_WIDTH, DINING_CUT_DEPTH),
      height: ROOM_HEIGHT,
      wallThickness: WALL,
      openings: OPENINGS.map((o) => ({ ...o })),
      partitions: PARTITIONS.map((p) => ({ ...p, a: { ...p.a }, b: { ...p.b } })),
    },
    items: SPECS.map((s, i) => specItem(s, i, lang)),
  };
}
